-- Access QueryDef: cn_PrDocImp_CnInvExCsosExPdNt
-- Type: 0

SELECT x.cn_key, x.CnNum, x.CnInvNum, x.CnInvDate, x.ciKey, x.inKeyCount, x.csosKey, x.AccountMain, x.ciasKey, x.cnpdTpOrd, x.cnpdTpOrdKey, x.cnpdNumNull, x.cnpdDateNull, x.cnpdKey, count(x.NumDate) AS NumDateCount
FROM (SELECT y.cn_key, y.CnNum, y.CnInvNum, y.CnInvDate, y.ciKey, y.inKeyCount, y.csosKey, y.AccountMain, y.ciasKey, y.cnpdTpOrd, y.cnpdTpOrdKey, y.cnpdNumNull, y.cnpdDateNull, y.cnpdKey, ags_cn_PrDoc.cnpdKey AS NumDate FROM (SELECT z.cn_key, z.CnNum, z.CnInvNum, z.CnInvDate, z.ciKey, z.inKeyCount, z.csosKey, z.AccountMain, z.ciasKey, z.cnpdTpOrd, z.cnpdTpOrdKey, z.cnpdNumNull, z.cnpdDateNull, d.cnpdKey FROM (SELECT e.cn_key, e.CnNum, e.CnInvNum, e.CnInvDate, e.ciKey, e.inKeyCount, e.csosKey, e.AccountMain, e.ciasKey, i.cnpdTpOrd, i.cnpdTpOrdKey, i.cnpdNumNull, i.cnpdDateNull FROM cn_PrDocImp_CnInvExCsosEx AS e LEFT JOIN cn_PrDocImp AS i ON (e.AccountMain = i.AccountMain) AND (e.CnInvDate = i.cnpdCnInvDateNull) AND (e.CnInvNum = i.cnpdCnInvNumNull) AND (e.CnNum = i.cnpdCnNumNull))  AS z LEFT JOIN ags_cn_PrDoc AS d ON (z.ciasKey = d.cnpdCnInvAccntSmpl) AND (z.cnpdNumNull = d.cnpdNumNull) AND (z.cnpdDateNull = d.cnpdDateNull) AND (z.cnpdTpOrdKey = d.cnpdTpOrd) GROUP BY z.cn_key, z.CnNum, z.CnInvNum, z.CnInvDate, z.ciKey, z.inKeyCount, z.csosKey, z.AccountMain, z.ciasKey, z.cnpdTpOrd, z.cnpdTpOrdKey, z.cnpdNumNull, z.cnpdDateNull, d.cnpdKey HAVING (((d.cnpdKey) Is Null)))  AS y LEFT JOIN ags_cn_PrDoc ON (y.cnpdDateNull = ags_cn_PrDoc.cnpdDateNull) AND (y.cnpdNumNull = ags_cn_PrDoc.cnpdNumNull) GROUP BY y.cn_key, y.CnNum, y.CnInvNum, y.CnInvDate, y.ciKey, y.inKeyCount, y.csosKey, y.AccountMain, y.ciasKey, y.cnpdTpOrd, y.cnpdTpOrdKey, y.cnpdNumNull, y.cnpdDateNull, y.cnpdKey, ags_cn_PrDoc.cnpdKey)  AS x
GROUP BY x.cn_key, x.CnNum, x.CnInvNum, x.CnInvDate, x.ciKey, x.inKeyCount, x.csosKey, x.AccountMain, x.ciasKey, x.cnpdTpOrd, x.cnpdTpOrdKey, x.cnpdNumNull, x.cnpdDateNull, x.cnpdKey;
